import{_ as a,o as t,c as o,a7 as l}from"./chunks/framework.FWlv_suP.js";const m=JSON.parse('{"title":"Scrollix Data Collection","description":"Official data collection information for Scrollix.","frontmatter":{"title":"Scrollix Data Collection","description":"Official data collection information for Scrollix.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/scrollix.md","filePath":"data-collection/scrollix.md"}'),i={name:"data-collection/scrollix.md"};function r(n,e,s,c,d,f){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="scrollix-data-collection" tabindex="-1">Scrollix Data Collection <a class="header-anchor" href="#scrollix-data-collection" aria-label="Permalink to &quot;Scrollix Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> August 1, 2026</p><h2 id="feed-and-local-data" tabindex="-1">Feed and local data <a class="header-anchor" href="#feed-and-local-data" aria-label="Permalink to &quot;Feed and local data&quot;">​</a></h2><p>Scrollix reads configured Google Sheet rows containing media types, URLs or IDs, protection flags, titles, descriptions, start times, and hashes. It caches the feed in unencrypted localStorage. Link-preview metadata and up to five full offline post pages may also be cached locally.</p><p>The app stores opening preferences, username and successful password hash, and optional PIN-verifier and biometric settings. Android performs biometric verification without exposing biometric templates to Scrollix.</p><h2 id="external-processing" tabindex="-1">External processing <a class="header-anchor" href="#external-processing" aria-label="Permalink to &quot;External processing&quot;">​</a></h2><p>Google, embedded media platforms, destination websites, and Microlink where used receive content requests, URLs or identifiers, and standard connection metadata. Scrollix has no developer-operated advertising, analytics, or telemetry.</p><p>Questions can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',8)])])}const h=a(i,[["render",r]]);export{m as __pageData,h as default};
